import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import "../styles/main.css";

/**
 * AdminStudentsFees.jsx
 * - Shows list of students (from /api/fees/admin/students)
 * - When selecting a student, shows class-based fee keys (only) + any extra (student overrides)
 * - Admin can update amounts for any visible key.
 * - Admin can add a new extra fee type (per-student).
 * - Admin can delete only extra fee types (default class keys are protected).
 * - Save sends { admissionNo, feeOverrides } to POST /api/fees/student
 */

export default function AdminStudentsFees() {
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState(null);
  const [overrides, setOverrides] = useState({}); // { key: amount }
  const [paid, setPaid] = useState(0);
  const [total, setTotal] = useState(0);
  const [remaining, setRemaining] = useState(0);
  const [loading, setLoading] = useState(false);

  // CLASS-BASED DEFAULTS (your rule):
  const getFeeKeysForClass = (cls) => {
    const c = Number(cls);
    if (!c || c < 1) return [];
    if (c >= 1 && c <= 5) return ["development", "transport"];
    if (c >= 6 && c <= 9) return ["tuition", "development", "transport"];
    return ["exam", "tuition", "development"];
  };

  // fetch students (admin list)
  const fetchStudents = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/fees/admin/students");
      if (res.data?.success || Array.isArray(res.data)) {
        // older endpoints returned data directly; handle both shapes
        setStudents(res.data.data || res.data);
      } else {
        setStudents([]);
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to load students");
    }
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  // select a student and load fee summary (server returns computed items/payments)
  const selectStudent = async (stu) => {
    setSelected(stu);
    setOverrides({});
    setPaid(0);
    setTotal(0);
    setRemaining(0);

    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${stu.admissionNo}`);
      if (!res.data?.success) {
        toast.error("Student fee record not found");
        return;
      }

      const payload = res.data.data;
      const student = payload.student || stu;
      const feeItems = payload.fee?.items || {}; // object: { key: { title, amount } }
      const payments = payload.payments || [];

      // Build overrides object (admin editable amounts)
      // Start with class-based keys in order, using override if present, else value from feeItems
      const classKeys = getFeeKeysForClass(student.classApplied || student.class);
      const resultOverrides = {};

      // Include class-based keys first
      classKeys.forEach((k) => {
        const amt = Number(feeItems[k]?.amount) || 0;
        resultOverrides[k] = amt;
      });

      // Include any extra keys from feeItems that are not in classKeys
      Object.keys(feeItems).forEach((k) => {
        if (!classKeys.includes(k)) {
          resultOverrides[k] = Number(feeItems[k]?.amount) || 0;
        }
      });

      // If backend returns student.feeOverrides (Map/object), prefer those values where present
      // But feeItems often already used override values — this is just defensive
      if (student.feeOverrides) {
        // student.feeOverrides could be a Map-like or plain object
        const fo = student.feeOverrides;
        // convert Map -> object if needed
        if (typeof fo.forEach === "function") {
          // Map
          fo.forEach((v, key) => {
            resultOverrides[key] = Number(v) || 0;
          });
        } else {
          // plain object
          Object.entries(fo).forEach(([key, v]) => {
            resultOverrides[key] = Number(v) || 0;
          });
        }
      }

      setOverrides(resultOverrides);

      // compute totals / paid / remaining
      const tot = Object.values(resultOverrides).reduce((s, v) => s + (Number(v) || 0), 0);
      const paidAmt = payments.reduce((s, t) => s + (Number(t.amount) || 0), 0);

      setTotal(tot);
      setPaid(paidAmt);
      setRemaining(Math.max(0, tot - paidAmt));
    } catch (err) {
      console.error(err);
      toast.error("Failed to load fee details");
    }
  };

  // update a fee amount (admin)
  const updateOverride = (key, value) => {
    const num = Number(value) || 0;
    setOverrides((prev) => {
      const updated = { ...prev, [key]: num };
      const tot = Object.values(updated).reduce((s, v) => s + (Number(v) || 0), 0);
      setTotal(tot);
      setRemaining(Math.max(0, tot - paid));
      return updated;
    });
  };

  // add an extra fee type
  const addFeeType = () => {
    const name = prompt("Enter new fee key (single word, e.g. 'dance' or 'library'):");
    if (!name) return;
    const key = name.trim();
    if (!key) return;
    if (overrides[key] !== undefined) {
      toast.error("Fee type already present for this student");
      return;
    }

    setOverrides((prev) => {
      const updated = { ...prev, [key]: 0 };
      const tot = Object.values(updated).reduce((s, v) => s + (Number(v) || 0), 0);
      setTotal(tot);
      setRemaining(Math.max(0, tot - paid));
      return updated;
    });
  };

  // delete an extra fee type (NOT allowed for class-based defaults)
  const deleteFeeType = (key) => {
    if (!selected) return;
    const defaultKeys = getFeeKeysForClass(selected.classApplied || selected.class);
    if (defaultKeys.includes(key)) {
      toast.error("Cannot delete class-default fee type");
      return;
    }

    if (!window.confirm(`Delete fee type "${key}" for ${selected.studentName}?`)) return;

    setOverrides((prev) => {
      const updated = { ...prev };
      delete updated[key];
      const tot = Object.values(updated).reduce((s, v) => s + (Number(v) || 0), 0);
      setTotal(tot);
      setRemaining(Math.max(0, tot - paid));
      return updated;
    });
  };

  // Save overrides to backend
  const saveChanges = async () => {
    if (!selected) {
      toast.error("Select a student first");
      return;
    }
    setLoading(true);
    try {
      // send overrides as plain object
      const res = await axios.post("http://localhost:5000/api/fees/student", {
        admissionNo: selected.admissionNo,
        feeOverrides: overrides,
      });

      if (res.data?.success) {
        toast.success("Fee overrides saved");
        // refetch students and selected student's data
        await fetchStudents();
        // reload selected student details
        if (selected?.admissionNo) selectStudent(selected);
      } else {
        toast.error(res.data?.error || "Save failed");
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to save changes");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="admin-fees-page">
      <Toaster />
      <h2 style={{ color: "#003366", fontSize: "24px" }}>Manage Student Fees</h2>
      <p>Edit class-based fees and add per-student extra fee types. Default class keys cannot be deleted.</p>

      <div style={{ display: "flex", gap: 20 }}>
        {/* Student List */}
        <div style={{ width: 300, borderRight: "1px solid #eee", paddingRight: 12 }}>
          <h3 style={{ marginTop: 0 }}>Students</h3>
          <div style={{ maxHeight: 520, overflow: "auto" }}>
            <ul style={{ listStyle: "none", padding: 0, margin: 0 }}>
              {students.map((s) => (
                <li
                  key={s._id}
                  onClick={() => selectStudent(s)}
                  style={{
                    padding: "8px 6px",
                    borderRadius: 6,
                    cursor: "pointer",
                    background: selected?._id === s._id ? "#eef6ff" : "transparent",
                    marginBottom: 6,
                  }}
                >
                  <div style={{ fontWeight: 700 }}>{s.studentName}</div>
                  <div style={{ fontSize: 12, color: "#666" }}>Admn: {s.admissionNo} — Class {s.classApplied || s.class}</div>
                </li>
              ))}
            </ul>
          </div>
        </div>

        {/* Fee Editor */}
        <div style={{ flex: 1 }}>
          {!selected ? (
            <div style={{ padding: 20 }}>Select a student to edit fees.</div>
          ) : (
            <div style={{ padding: 10 }}>
              <h3 style={{ marginTop: 0 }}>
                Edit Fees — {selected.studentName} (Class {selected.classApplied || selected.class})
              </h3>

              <div style={{ marginBottom: 8 }}>
                <button onClick={addFeeType} style={{ marginRight: 8 }}>+ Add Fee Type</button>
                <button onClick={() => { setOverrides({}); selectStudent(selected); }} style={{ marginRight: 8 }}>
                  Reset to server values
                </button>
              </div>

              <table className="fee-table" style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr>
                    <th style={{ textAlign: "left", padding: 8, borderBottom: "1px solid #ddd" }}>Fee Type</th>
                    <th style={{ textAlign: "right", padding: 8, borderBottom: "1px solid #ddd" }}>Amount (₹)</th>
                  </tr>
                </thead>
                <tbody>
                  {Object.entries(overrides).map(([key, val]) => (
                    <tr key={key}>
                      <td style={{ padding: 8, borderBottom: "1px solid #f2f2f2" }}>
                        <span style={{ fontWeight: 600 }}>{key}</span>
                        {/* delete icon (only for extras) */}
                        {!getFeeKeysForClass(selected.classApplied || selected.class).includes(key) && (
                          <button
                            title="Delete extra fee type"
                            onClick={() => deleteFeeType(key)}
                            style={{
                              marginLeft: 12,
                              border: "none",
                              background: "transparent",
                              cursor: "pointer",
                              color: "#c0392b",
                            }}
                          >
                            🗑
                          </button>
                        )}
                      </td>
                      <td style={{ padding: 8, borderBottom: "1px solid #f2f2f2", textAlign: "right" }}>
                        <input
                          type="number"
                          value={val}
                          onChange={(e) => updateOverride(key, e.target.value)}
                          style={{ width: 120, textAlign: "right", padding: "6px 8px" }}
                        />
                      </td>
                    </tr>
                  ))}

                  <tr>
                    <td style={{ padding: 8, borderTop: "2px solid #ddd" }}><b>Total</b></td>
                    <td style={{ padding: 8, borderTop: "2px solid #ddd", textAlign: "right" }}><b>₹{(total || 0).toLocaleString()}</b></td>
                  </tr>
                  <tr>
                    <td style={{ padding: 8 }}>Paid</td>
                    <td style={{ padding: 8, textAlign: "right" }}>₹{(paid || 0).toLocaleString()}</td>
                  </tr>
                  <tr>
                    <td style={{ padding: 8 }}>Remaining</td>
                    <td style={{ padding: 8, textAlign: "right" }}>₹{(remaining || 0).toLocaleString()}</td>
                  </tr>
                </tbody>
              </table>

              <div style={{ marginTop: 12 }}>
                <button onClick={saveChanges} disabled={loading}>
                  {loading ? "Saving..." : "Save Changes"}
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
